INSERT INTO "products" VALUES('20948481','Zitronenkuchen Backmischung','Pisa','500g',500.0,'g',NULL,NULL,'["en:snacks", "en:sweet-snacks", "en:biscuits-and-cakes", "en:baby-foods", "en:baby-milks", "en:cakes", "en:cooking-helpers", "en:baking-mixes", "en:dessert-mixes", "en:infant-formulas", "en:pastry-helpers", "en:cake-mixes", "en:baby-start-milk-from-10-months"]','["en:germany"]','["xx:pisa"]','https://images.openfoodfacts.org/images/products/20948481/4.400.jpg','de',1774517727,'2026-03-26',370.0,1550.0,4.0,1.0,0.800000011920929,85.0,50.0,NULL,400.0,'sodium',NULL,'Noch hinzufügen: Für den Teig: 3 Eier (Größe M) 80 ml Milch (1,5 % Fett) 150 g Margarine Für die Form: Puda etwas Fett und Mehl Für die Glasur: etwas Wasser Backmischung. für einen Rührkuchen mit einer Zuckerglasur mit Zitronengeschmack Zubereitung: 1. Teig zubereiten: Backofen vorheizen. Die Backmischung, Margarine, Eier und Milch in eine Rührschüssel geben und mit einem elektrischen Handrührgerät (Rührbesen) erst kurz auf niedrigster Stufe verrühren, dann auf höchster Stufe ca. 3 Minuten cremig rühren. 2. Backen: Eine Kastenform (25 cm) fetten und mehlen, den Teig hineingeben und glatt streichen. Den Kuchen im unteren Drittel des Ofens backen. Nach ca. 15 Minuten Backzeit den Kuchen der Länge nach einschneiden und weitere 45 Minuten backen. Vor dem Herausnehmen mit einem Holzstäbchen prüfen, ob der Kuchen gar ist. Ober - / Unterhitze: 180 °C (vorgeheizt) Umluft: 160 °C (vorgeheizt) Einschub: Mitte Backzeit: ca. 60 Minuten (Stäbchenprobe) Siehe auch Geräteanleitung! 3. Auskühlen und Glasieren: Den frisch gebackenen Kuchen einige Minuten abkühlen lassen, mit einem Messer vorsichtig aus der Form lösen, auf ein Kuchengitter stürzen und erkalten lassen. Den Inhalt des Glasurbeutels in eine kleine Schüssel geben, löffelweise nach und nach nur so viel Wasser unterrühren, dass ein dickflüssiger Guss entsteht. Den Kuchen mit der Glasur bestreichen.','["de:noch-hinzufügen", "de:3-eier", "en:milk", "en:dairy", "de:margarine-für-die-form", "de:etwas-wasser-backmischung", "de:für-einen-rührkuchen-mit-einer-zuckerglasur-mit-zitronengeschmack-zubereitung", "de:backofen-vorheizen", "de:die-backmischung", "en:margarine", "en:egg", "de:milch-in-eine-rührschüssel-geben-und-mit-einem-elektrischen-handrührgerät", "de:erst-kurz-auf-niedrigster-stufe-verrühren", "de:dann-auf-höchster-stufe-ca", "de:3-minuten-cremig-rühren", "de:2", "de:backen", "de:den-teig-hineingeben-und-glatt-streichen", "de:den-kuchen-im-unteren-drittel-des-ofens-backen", "de:nach-ca", "de:15-minuten-backzeit-den-kuchen-der-länge-nach-einschneiden-und-weitere-45-minuten-backen", "de:vor-dem-herausnehmen-mit-einem-holzstäbchen-prüfen", "de:ob-der-kuchen-gar-ist", "de:ober", "de:unterhitze", "de:160-c", "de:einschub", "de:ca", "de:60-minuten", "de:siehe-auch-geräteanleitung-3", "de:auskühlen-und-glasieren", "de:mit-einem-messer-vorsichtig-aus-der-form-lösen", "de:auf-ein-kuchengitter-stürzen-und-erkalten-lassen", "de:den-inhalt-des-glasurbeutels-in-eine-kleine-schüssel-geben", "de:löffelweise-nach-und-nach-nur-so-viel-wasser-unterrühren", "de:dass-ein-dickflüssiger-guss-entsteht", "de:den-kuchen-mit-der-glasur-bestreichen", "de:für-den-teig", "de:größe-m", "en:fat", "en:oil-and-fat", "de:puda-etwas-fett-und-mehl-für-die-glasur", "de:1", "de:teig-zubereiten", "de:rührbesen", "de:eine-kastenform", "de:fetten-und-mehlen", "de:180-c", "de:umluft", "de:vorgeheizt", "de:mitte-backzeit", "de:stäbchenprobe", "de:den-frisch-gebackenen-kuchen-einige-minuten-abkühlen-lassen", "de:25-cm"]',NULL,'["en:eggs", "en:milk"]','["en:nutriscore", "en:nutriscore-grade-e"]','["en:baby-foods-and-milks", "en:baby-milks"]',NULL,NULL,'not-applicable',NULL,'Pisa');
