INSERT INTO "products" VALUES('4600338008424','детское Молоко с печеньем','ФрутоНЯНЯ','200гр.',NULL,NULL,NULL,NULL,'["en:dairies", "en:baby-foods", "en:milks"]','["en:russia"]','["фрутоняня"]','https://images.openfoodfacts.org/images/products/460/033/800/8424/1.400.jpg','ru',1711452660,'2024-03-26',73.5999984741211,308.0,3.20000004768371582031e+00,2.40000009536743164062e+00,NULL,9.80000019073486328125e+00,4.0,NULL,NULL,NULL,'100g','RU/BY КОКТЕЙЛЬ МОЛОЧНЫЙ С ПЕЧЕНЬЕМ «МОЛОКО С ПЕЧЕНЬЕМ» СТЕРИЛИЗО - ВАННЫЙ, С МАССОВОЙ ДОЛЕЙ ЖИРА 2,4% ДЛЯ ПИТАНИЯ ДЕТЕЙ РАННЕГО ВОЗРАСТА. СОСТАВ (соответствующую букву-код смотрите на верх - ней панели пакета): А - молоко нормализованное, сахар, печенье растворимое (мука пшеничная, сахар, масло сливочное, яйцо куриное (меланж яичный), экстракт со - лодовый, молоко сухое цельное, крахмал кукурузный, разрыхлитель: гидрокарбонат натрия), ароматизатор на - туральный; В - молоко восстановленное, сахар, печенье растворимое (мука пшеничная, сахар, масло сливочное, яйцо куриное (меланж яичный), экстракт солодовый, мо - локо сухое цельное, крахмал кукурузный, разрыхлитель: гидрокарбонат натрия), ароматизатор натуральный. РЕКОМЕНДАЦИИ ПО УПОТРЕБЛЕНИЮ: продукт готов к упо - треблению. Рекомендуется детям с 12 месяцев, начиная с небольших количеств и постепенно увеличивая до разовой порции 50-70 г. Перед употреблением взбалтывать. УСЛО - ВИЯ ХРАНЕНИЯ: хранить при температуре от 0°С до +25°С и относительной влажности воздуха не более 75%. Беречь от солнечных лучей. Вскрытую упаковку хранить в холодиль - нике не более суток. ПИЩЕВАЯ ЦЕННОСТЬ НА 100 Г (СРЕДНИЕ ЗНАЧЕНИЯ) / 100 Г ӨНІМНІҢ ТАҒАМДЫҚ ҚҰНДЫЛЫҒЫ (ОРТАША МӘНДЕРІ) / 100 G MAHSULOTNING OZUQAVIY QIMMATI (O''RTACHA QIYMATLAR): жир, г / май, г / yog'', 9 белок, г / ақуыз, г / oqsil, g углеводы, г/ көмірсулар, г / uglevodlar, g сахароза, г / shu jumladan, qo''shilgan saxaroza, g в том числе добавленная сахароза, г / соның ішінде қосылған 2,4 3,2 9,8 4,0 энергетическая ценность (калорийность), кДж/ккал / қуаттылық құндылығы (жұғымдылығы), кДж / ккал / energetik qimmati (kaloriyaliligi), kDj / kkal 308,1/73,6 минеральные вещества: / минералды заттар: кальций (справочно), мг/ кальций (анықтамалық), мг/ kalsiy (ma''lumot uchun), mg 90-160','["ru:ru", "ru:by-коктейль-молочный-с-печеньем-молоко-с-печеньем-стерилизо", "ru:ванный", "ru:с-массовой-долей-жира-2-4-для-питания-детей-раннего-возраста", "en:milk", "en:dairy", "en:sugar", "en:added-sugar", "en:disaccharide", "ru:печенье-растворимое", "ru:ароматизатор-на", "ru:туральный", "ru:в", "ru:молоко-восстановленное", "en:natural-flavouring", "en:flavouring", "ru:рекомендации-по-употреблению", "ru:треблению", "ru:рекомендуется-детям-с-12-месяцев", "ru:начиная-с-небольших-количеств-и-постепенно-увеличивая-до-разовой-порции-50-70-г", "ru:перед-употреблением-взбалтывать", "ru:усло", "ru:вия-хранения", "ru:нике-не-более-суток", "ru:пищевая-ценность-на-100-г", "ru:100-г-өнімнің-тағамдық-құндылығы", "ru:mahsulotning-ozuqaviy-qimmati", "ru:г", "ru:май", "ru:yog", "ru:9-белок", "ru:ақуыз", "ru:oqsil", "ru:g-углеводы", "ru:көмірсулар", "ru:uglevodlar", "ru:g-сахароза", "ru:shu-jumladan", "ru:qo-shilgan-saxaroza", "ru:g-в-том-числе-добавленная-сахароза", "ru:соның-ішінде-қосылған-2-4-3-2-9-8-4-0-энергетическая-ценность", "ru:кдж", "ru:ккал", "ru:қуаттылық-құндылығы", "ru:energetik-qimmati", "ru:kdj", "ru:kkal-308-1", "ru:73-6-минеральные-вещества", "en:calcium", "en:minerals", "ru:мг", "ru:kalsiy", "ru:mg-90-160", "ru:а", "en:wheat-flour", "en:cereal", "en:flour", "en:wheat", "en:cereal-flour", "en:butter", "en:chicken-egg", "en:egg", "ru:экстракт-со", "ru:лодовый", "en:whole-milk-powder", "en:milk-powder", "en:corn-starch", "en:starch", "en:raising-agent", "en:malt-extract", "en:extract", "en:malt", "en:vegetable-extract", "ru:мо", "ru:локо-сухое-цельное", "ru:продукт-готов-к-упо", "ru:хранить-при-температуре-от-0-с-до-25-с-и-относительной-влажности-воздуха-не-более", "ru:беречь-от-солнечных-лучей", "ru:вскрытую-упаковку-хранить-